    'privacy_title': 'Privacy Policy',
    'privacy_last_update': 'Last updated: {year}',
    'privacy_s1_title': '1. Who we are',
    'privacy_s1_body1':
        'Binome is a mobile app designed for couples, built to stay a private space exclusive to two people. This policy explains what data we collect, why, and how you can control it.',
    'privacy_s1_body2':
        'For any question about your data: contact@binome-app.com.',
    'privacy_s2_title': '2. The data we collect',
    'privacy_s2_sub1_title': 'Account information',
    'privacy_s2_sub1_body':
        'Email, first name, last name, gender, country of residence, profile photo, preferred language and theme. If you sign in with Google, some of this information comes directly from your Google account.',
    'privacy_s2_sub2_title': 'Information linked to your couple ("Box")',
    'privacy_s2_sub2_body':
        'Your pairing code, your "together since" date, a couple photo, a shared motto/quote, and your reminder preferences (evening/morning rituals).',
    'privacy_s2_sub3_title': 'Content you exchange',
    'privacy_s2_sub3_body':
        'Poems, gifts, messages, photos, game answers, reactions — everything you send to your binôme within the app.',
    'privacy_s2_sub4_title': 'Payment data',
    'privacy_s2_sub4_body':
        'If you buy virtual Tokens, payment information is processed directly by our third-party payment provider; we never store your full bank details, only your transaction history (amount, currency, date).',
    'privacy_s2_sub5_title': 'Technical data',
    'privacy_s2_sub5_body':
        'Push notification token (to send you reminders), last-activity timestamp, and device information needed for the service to work properly.',
    'privacy_s3_title': '3. How we use this data',
    'privacy_s3_bullet1': "• Run your account and your couple space",
    'privacy_s3_bullet2':
        "• Send you the notifications you've enabled (reminders, alerts)",
    'privacy_s3_bullet3': '• Process your virtual Token purchases',
    'privacy_s3_bullet4': '• Keep the service secure and prevent abuse',
    'privacy_s3_bullet5': '• Improve the app',
    'privacy_s3_note':
        '\nWe never use your couple exchanges (messages, poems, photos) for advertising or AI-generated content.',
    'privacy_s4_title': '4. Sharing with third parties',
    'privacy_s4_intro': 'Your data may be shared, strictly as needed, with:',
    'privacy_s4_bullet1':
        '• Google (Google Sign-In, push notifications via Firebase)',
    'privacy_s4_bullet2':
        '• A third-party payment provider, for secure purchase processing',
    'privacy_s4_bullet3':
        '• Our hosting provider, located in the European Union',
    'privacy_s4_note':
        '\nWe never sell or rent your data to third parties for advertising purposes.',
    'privacy_s5_title': '5. Security and retention',
    'privacy_s5_body':
        "Your data is stored on servers located in the European Union, with encrypted passwords and authentication tokens. It is kept as long as your account is active, and permanently deleted (along with your Box's data, in cascade) if you delete your account.",
    'privacy_s6_title': '6. Your rights',
    'privacy_s6_intro': 'At any time, you can:',
    'privacy_s6_bullet1': '• View and edit your profile information',
    'privacy_s6_bullet2':
        '• Permanently delete your account from Settings → Danger zone',
    'privacy_s6_bullet3': '• Contact us with any question about your data',
    'privacy_s7_title': '7. Minimum age',
    'privacy_s7_body': 'Binome is intended for people aged 16 and older.',
    'privacy_s8_title': '8. Changes',
    'privacy_s8_body':
        'This policy may evolve; any substantial change will be notified to you within the app.',
