    'terms_title': 'Nutzungsbedingungen',
    'terms_last_update': 'Zuletzt aktualisiert: {year}',
    'terms_s1_title': '1. Annahme der Bedingungen',
    'terms_s1_body':
        'Durch das Erstellen eines Kontos oder die Nutzung von Binome stimmst du diesen Nutzungsbedingungen zu. Falls du nicht einverstanden bist, nutze die App bitte nicht.',
    'terms_s2_title': '2. Wer Binome nutzen darf',
    'terms_s2_body':
        'Binome richtet sich an Personen ab 16 Jahren im Rahmen einer frei vereinbarten Paarbeziehung. Jedes Konto ist persönlich; das Teilen von Zugangsdaten ist untersagt.',
    'terms_s3_title': '3. Dein Konto',
    'terms_s3_body':
        'Du bist für die Vertraulichkeit deiner Zugangsdaten und für jede Aktivität über dein Konto verantwortlich. Informiere uns sofort bei unbefugtem Zugriff.',
    'terms_s4_title': '4. Die Paarverbindung („Box“)',
    'terms_s4_body':
        'Der Beitritt zu oder die Erstellung einer Box schafft eine exklusive Verbindung zwischen zwei Personen. Ihr könnt diese Verbindung jederzeit über Einstellungen → Gefahrenzone beenden; geteilte Inhalte (Gedichte, Fotos, Spielantworten...) werden dann endgültig gelöscht.',
    'terms_s5_title': '5. Inhalte, die du teilst',
    'terms_s5_body1':
        'Du bleibst Eigentümer·in der Inhalte, die du deinem Binôme sendest (Nachrichten, Fotos, Gedichte, Spielantworten). Du gewährst uns nur das technische Recht, sie zu hosten und an dein Binôme zu übermitteln, niemals sie anderweitig zu nutzen.',
    'terms_s5_body2':
        'Du verpflichtest dich, keine rechtswidrigen, belästigenden Inhalte oder Inhalte zu senden, die Rechte Dritter verletzen.',
    'terms_s6_title': '6. Virtuelle Tokens und Käufe',
    'terms_s6_body':
        'Binome bietet käufliche virtuelle Tokens an, die für bestimmte Shop-Funktionen genutzt werden können. Käufe werden von unserem externen Zahlungsdienstleister abgewickelt. Tokens haben keinen realen Geldwert und sind weder erstattungsfähig noch übertragbar, außer wenn gesetzlich vorgeschrieben.',
    'terms_s7_title': '7. Sperrung und Kündigung',
    'terms_s7_body':
        'Wir können ein Konto bei eindeutigem Verstoß gegen diese Bedingungen (illegale Inhalte, Belästigung, Betrug) sperren oder löschen. Du kannst dein Konto jederzeit über Einstellungen → Gefahrenzone löschen.',
    'terms_s8_title': '8. Verfügbarkeit des Dienstes',
    'terms_s8_body':
        'Wir bemühen uns, Binome verfügbar zu halten, ohne eine unterbrechungsfreie Verfügbarkeit zu garantieren. Der Dienst kann sich weiterentwickeln, für Wartungsarbeiten vorübergehend unterbrochen oder geändert werden.',
    'terms_s9_title': '9. Haftungsbeschränkung',
    'terms_s9_body':
        'Binome wird „wie besehen" bereitgestellt. Soweit gesetzlich zulässig, haften wir nicht für indirekte Schäden, die aus der Nutzung der App entstehen.',
    'terms_s10_title': '10. Änderungen',
    'terms_s10_body':
        'Diese Bedingungen können sich weiterentwickeln; jede wesentliche Änderung wird dir in der App mitgeteilt.',
    'terms_s11_title': '11. Kontakt',
    'terms_s11_body':
        'Bei Fragen zu diesen Bedingungen: contact@binome-app.com.',
