    'privacy_title': 'Datenschutzrichtlinie',
    'privacy_last_update': 'Zuletzt aktualisiert: {year}',
    'privacy_s1_title': '1. Wer wir sind',
    'privacy_s1_body1':
        'Binome ist eine mobile App für Paare, konzipiert als privater Raum, der ausschließlich zwei Personen vorbehalten ist. Diese Richtlinie erklärt, welche Daten wir erheben, warum, und wie du sie kontrollieren kannst.',
    'privacy_s1_body2': 'Bei Fragen zu deinen Daten: contact@binome-app.com.',
    'privacy_s2_title': '2. Welche Daten wir erheben',
    'privacy_s2_sub1_title': 'Kontoinformationen',
    'privacy_s2_sub1_body':
        'E-Mail, Vorname, Nachname, Geschlecht, Wohnsitzland, Profilbild, bevorzugte Sprache und Design. Wenn du dich über Google anmeldest, stammen einige dieser Informationen direkt von deinem Google-Konto.',
    'privacy_s2_sub2_title': 'Informationen zu eurem Paar („Box“)',
    'privacy_s2_sub2_body':
        'Euer Verbindungscode, euer „zusammen seit“-Datum, ein Paarfoto, ein gemeinsames Motto/Zitat und eure Erinnerungseinstellungen (Abend-/Morgenrituale).',
    'privacy_s2_sub3_title': 'Inhalte, die ihr austauscht',
    'privacy_s2_sub3_body':
        'Gedichte, Geschenke, Nachrichten, Fotos, Spielantworten, Reaktionen — alles, was du deinem Binôme innerhalb der App sendest.',
    'privacy_s2_sub4_title': 'Zahlungsdaten',
    'privacy_s2_sub4_body':
        'Wenn du virtuelle Tokens kaufst, werden Zahlungsinformationen direkt von unserem externen Zahlungsdienstleister verarbeitet; wir speichern niemals deine vollständigen Bankdaten, nur deinen Transaktionsverlauf (Betrag, Währung, Datum).',
    'privacy_s2_sub5_title': 'Technische Daten',
    'privacy_s2_sub5_body':
        'Push-Benachrichtigungstoken (um dir Erinnerungen zu senden), Zeitstempel der letzten Aktivität sowie Geräteinformationen, die für den ordnungsgemäßen Betrieb des Dienstes erforderlich sind.',
    'privacy_s3_title': '3. Wie wir diese Daten nutzen',
    'privacy_s3_bullet1': '• Um dein Konto und euren Paar-Bereich zu betreiben',
    'privacy_s3_bullet2':
        '• Um dir aktivierte Benachrichtigungen zu senden (Erinnerungen, Hinweise)',
    'privacy_s3_bullet3': '• Um deine Käufe virtueller Tokens zu verarbeiten',
    'privacy_s3_bullet4':
        '• Um die Sicherheit zu gewährleisten und Missbrauch zu verhindern',
    'privacy_s3_bullet5': '• Um die App zu verbessern',
    'privacy_s3_note':
        '\nWir nutzen eure Paar-Inhalte (Nachrichten, Gedichte, Fotos) niemals für Werbung oder KI-generierte Inhalte.',
    'privacy_s4_title': '4. Weitergabe an Dritte',
    'privacy_s4_intro':
        'Deine Daten können, streng im erforderlichen Rahmen, weitergegeben werden an:',
    'privacy_s4_bullet1':
        '• Google (Anmeldung über Google Sign-In, Push-Benachrichtigungen über Firebase)',
    'privacy_s4_bullet2':
        '• Einen externen Zahlungsdienstleister, für die sichere Abwicklung von Käufen',
    'privacy_s4_bullet3':
        '• Unseren Hosting-Anbieter mit Sitz in der Europäischen Union',
    'privacy_s4_note':
        '\nWir verkaufen oder vermieten deine Daten niemals an Dritte zu Werbezwecken.',
    'privacy_s5_title': '5. Sicherheit und Aufbewahrung',
    'privacy_s5_body':
        'Deine Daten werden auf Servern in der Europäischen Union gespeichert, mit verschlüsselten Passwörtern und Authentifizierungstoken. Sie werden aufbewahrt, solange dein Konto aktiv ist, und bei Kontolöschung dauerhaft gelöscht (zusammen mit den Daten eurer Box, kaskadierend).',
    'privacy_s6_title': '6. Deine Rechte',
    'privacy_s6_intro': 'Du kannst jederzeit:',
    'privacy_s6_bullet1': '• Deine Profilinformationen einsehen und bearbeiten',
    'privacy_s6_bullet2':
        '• Dein Konto endgültig löschen über Einstellungen → Gefahrenzone',
    'privacy_s6_bullet3': '• Uns bei jeder Frage zu deinen Daten kontaktieren',
    'privacy_s7_title': '7. Mindestalter',
    'privacy_s7_body': 'Binome richtet sich an Personen ab 16 Jahren.',
    'privacy_s8_title': '8. Änderungen',
    'privacy_s8_body':
        'Diese Richtlinie kann sich weiterentwickeln; jede wesentliche Änderung wird dir in der App mitgeteilt.',
