    'privacy_title': 'Política de privacidad',
    'privacy_last_update': 'Última actualización: {year}',
    'privacy_s1_title': '1. Quiénes somos',
    'privacy_s1_body1':
        'Binome es una aplicación móvil para parejas, pensada para seguir siendo un espacio privado y exclusivo para dos personas. Esta política explica qué datos recopilamos, por qué y cómo puedes controlarlos.',
    'privacy_s1_body2':
        'Para cualquier pregunta sobre tus datos: contact@binome-app.com.',
    'privacy_s2_title': '2. Los datos que recopilamos',
    'privacy_s2_sub1_title': 'Información de la cuenta',
    'privacy_s2_sub1_body':
        'Email, nombre, apellido, género, país de residencia, foto de perfil, idioma y tema preferidos. Si te conectas con Google, parte de esta información proviene directamente de tu cuenta de Google.',
    'privacy_s2_sub2_title': 'Información vinculada a tu pareja («Box»)',
    'privacy_s2_sub2_body':
        'Tu código de emparejamiento, tu fecha de "juntos desde", una foto de pareja, una divisa/frase compartida y tus preferencias de recordatorios (rituales de noche/mañana).',
    'privacy_s2_sub3_title': 'Contenido que intercambian',
    'privacy_s2_sub3_body':
        'Poemas, regalos, mensajes, fotos, respuestas de juegos, reacciones — todo lo que envías a tu binôme dentro de la aplicación.',
    'privacy_s2_sub4_title': 'Datos de pago',
    'privacy_s2_sub4_body':
        'Si compras Tokens virtuales, la información de pago es procesada directamente por nuestro proveedor de pagos externo; nunca almacenamos tus datos bancarios completos, solo tu historial de transacciones (importe, moneda, fecha).',
    'privacy_s2_sub5_title': 'Datos técnicos',
    'privacy_s2_sub5_body':
        'Token de notificaciones push (para enviarte recordatorios), marca de tiempo de última actividad e información del dispositivo necesaria para el buen funcionamiento del servicio.',
    'privacy_s3_title': '3. Cómo usamos estos datos',
    'privacy_s3_bullet1':
        '• Hacer funcionar tu cuenta y vuestro espacio de pareja',
    'privacy_s3_bullet2':
        '• Enviarte las notificaciones que has activado (recordatorios, alertas)',
    'privacy_s3_bullet3': '• Procesar tus compras de Tokens virtuales',
    'privacy_s3_bullet4': '• Garantizar la seguridad y prevenir abusos',
    'privacy_s3_bullet5': '• Mejorar la aplicación',
    'privacy_s3_note':
        '\nNunca usamos vuestros intercambios de pareja (mensajes, poemas, fotos) con fines publicitarios ni para contenido generado por IA.',
    'privacy_s4_title': '4. Compartir con terceros',
    'privacy_s4_intro':
        'Tus datos pueden transmitirse, en la estricta medida necesaria, a:',
    'privacy_s4_bullet1':
        '• Google (inicio de sesión con Google, notificaciones push vía Firebase)',
    'privacy_s4_bullet2':
        '• Un proveedor de pagos externo, para el procesamiento seguro de compras',
    'privacy_s4_bullet3':
        '• Nuestro proveedor de alojamiento, ubicado en la Unión Europea',
    'privacy_s4_note':
        '\nNunca vendemos ni alquilamos tus datos a terceros con fines publicitarios.',
    'privacy_s5_title': '5. Seguridad y conservación',
    'privacy_s5_body':
        'Tus datos se almacenan en servidores ubicados en la Unión Europea, con contraseñas y tokens de autenticación cifrados. Se conservan mientras tu cuenta esté activa y se eliminan definitivamente (junto con los de tu Box, en cascada) si eliminas tu cuenta.',
    'privacy_s6_title': '6. Tus derechos',
    'privacy_s6_intro': 'En cualquier momento puedes:',
    'privacy_s6_bullet1': '• Consultar y modificar tu información de perfil',
    'privacy_s6_bullet2':
        '• Eliminar tu cuenta definitivamente desde Ajustes → Zona de peligro',
    'privacy_s6_bullet3':
        '• Contactarnos por cualquier pregunta sobre tus datos',
    'privacy_s7_title': '7. Edad mínima',
    'privacy_s7_body': 'Binome está destinado a personas de 16 años o más.',
    'privacy_s8_title': '8. Modificaciones',
    'privacy_s8_body':
        'Esta política puede evolucionar; cualquier cambio sustancial te será notificado dentro de la aplicación.',
