    'terms_title': 'شروط الخدمة',
    'terms_last_update': 'آخر تحديث: {year}',
    'terms_s1_title': '1. قبول الشروط',
    'terms_s1_body':
        'بإنشاء حساب أو استخدام Binome، فإنك توافق على شروط الخدمة هذه. إذا كنت لا توافق، يُرجى عدم استخدام التطبيق.',
    'terms_s2_title': '2. من يمكنه استخدام Binome',
    'terms_s2_body':
        'Binome مخصّص للأشخاص البالغين 16 عاماً فأكثر، في إطار علاقة ثنائية بالتراضي الحر. كل حساب شخصي؛ يُمنع مشاركة بيانات الدخول.',
    'terms_s3_title': '3. حسابك',
    'terms_s3_body':
        'أنت مسؤول عن سرية بيانات الدخول الخاصة بك وعن أي نشاط يتم من حسابك. أخبرنا فوراً في حال وجود وصول غير مصرح به.',
    'terms_s4_title': '4. رابط الثنائي ("Box")',
    'terms_s4_body':
        'الانضمام إلى Box أو إنشاؤه ينشئ رابطاً حصرياً بين شخصين. يمكنكما إنهاء هذا الرابط في أي وقت من الإعدادات ← المنطقة الخطرة؛ عندها يُحذف المحتوى المشترك (القصائد، الصور، إجابات الألعاب...) نهائياً.',
    'terms_s5_title': '5. المحتوى الذي تشاركه',
    'terms_s5_body1':
        'تظل مالكاً للمحتوى الذي ترسله لشريكك (رسائل، صور، قصائد، إجابات الألعاب). أنت تمنحنا فقط الحق التقني في استضافته ونقله إلى شريكك، وليس أبداً استخدامه لأغراض أخرى.',
    'terms_s5_body2':
        'تتعهد بعدم إرسال محتوى غير قانوني أو مضايق أو ينتهك حقوق طرف ثالث.',
    'terms_s6_title': '6. Token الافتراضية والمشتريات',
    'terms_s6_body':
        'يقدّم Binome Token افتراضية قابلة للشراء، تُستخدم لبعض ميزات المتجر. تتم معالجة المشتريات من قِبل مزوّد الدفع الخارجي الخاص بنا. Token لا تملك أي قيمة نقدية حقيقية، وهي غير قابلة للاسترداد أو التحويل، ما لم ينص القانون على خلاف ذلك.',
    'terms_s7_title': '7. التعليق والإنهاء',
    'terms_s7_body':
        'يمكننا تعليق أو حذف حساب في حال وجود انتهاك واضح لهذه الشروط (محتوى غير قانوني، مضايقة، احتيال). يمكنك حذف حسابك في أي وقت من الإعدادات ← المنطقة الخطرة.',
    'terms_s8_title': '8. توفر الخدمة',
    'terms_s8_body':
        'نبذل قصارى جهدنا للحفاظ على توفر Binome، دون ضمان توفر مستمر بلا انقطاع. قد تتطور الخدمة أو تتوقف مؤقتاً للصيانة أو تُعدَّل.',
    'terms_s9_title': '9. تحديد المسؤولية',
    'terms_s9_body':
        'يُقدَّم Binome "كما هو". وفي الحدود التي يسمح بها القانون، لسنا مسؤولين عن الأضرار غير المباشرة الناتجة عن استخدام التطبيق.',
    'terms_s10_title': '10. التعديلات',
    'terms_s10_body':
        'قد تتطور هذه الشروط؛ سيتم إعلامك بأي تعديل جوهري داخل التطبيق.',
    'terms_s11_title': '11. التواصل',
    'terms_s11_body': 'لأي سؤال يتعلق بهذه الشروط: contact@binome-app.com.',
    'common_enable': 'تفعيل',
    'notif_card_title': 'الإشعارات معطّلة',
