    'privacy_title': 'سياسة الخصوصية',
    'privacy_last_update': 'آخر تحديث: {year}',
    'privacy_s1_title': '1. من نحن',
    'privacy_s1_body1':
        'Binome هو تطبيق جوّال مخصّص للأزواج، صُمِّم ليبقى مساحة خاصة وحصرية لشخصين. توضّح هذه السياسة البيانات التي نجمعها، ولماذا، وكيف يمكنك التحكم بها.',
    'privacy_s1_body2': 'لأي سؤال يتعلق ببياناتك: contact@binome-app.com.',
    'privacy_s2_title': '2. البيانات التي نجمعها',
    'privacy_s2_sub1_title': 'معلومات الحساب',
    'privacy_s2_sub1_body':
        'البريد الإلكتروني، الاسم الأول، اسم العائلة، الجنس، بلد الإقامة، صورة الملف الشخصي، اللغة والسمة المفضلتان. إذا سجّلت الدخول عبر Google، فقد تأتي بعض هذه المعلومات مباشرة من حسابك على Google.',
    'privacy_s2_sub2_title': 'المعلومات المرتبطة بثنائيكما ("Box")',
    'privacy_s2_sub2_body':
        'رمز الاقتران، تاريخ "معاً منذ"، صورة الثنائي، شعار/اقتباس مشترك، وتفضيلات التذكير الخاصة بكما (طقوس المساء/الصباح).',
    'privacy_s2_sub3_title': 'المحتوى الذي تتبادلانه',
    'privacy_s2_sub3_body':
        'القصائد، الهدايا، الرسائل، الصور، إجابات الألعاب، التفاعلات — كل ما ترسله لشريكك داخل التطبيق.',
    'privacy_s2_sub4_title': 'بيانات الدفع',
    'privacy_s2_sub4_body':
        'إذا اشتريت Token افتراضية، تتم معالجة معلومات الدفع مباشرة من قِبل مزوّد الدفع الخارجي؛ لا نخزّن أبداً بياناتك المصرفية الكاملة، بل فقط سجل معاملاتك (المبلغ، العملة، التاريخ).',
    'privacy_s2_sub5_title': 'البيانات التقنية',
    'privacy_s2_sub5_body':
        'رمز الإشعارات الفورية (لإرسال التذكيرات إليك)، الطابع الزمني لآخر نشاط، ومعلومات الجهاز اللازمة لحسن سير الخدمة.',
    'privacy_s3_title': '3. كيف نستخدم هذه البيانات',
    'privacy_s3_bullet1': '• تشغيل حسابك ومساحة ثنائيكما',
    'privacy_s3_bullet2': '• إرسال الإشعارات التي فعّلتها (تذكيرات، تنبيهات)',
    'privacy_s3_bullet3': '• معالجة مشترياتك من Token الافتراضية',
    'privacy_s3_bullet4': '• ضمان الأمان ومنع الإساءة',
    'privacy_s3_bullet5': '• تحسين التطبيق',
    'privacy_s3_note':
        '\nلا نستخدم أبداً تبادلاتكما الخاصة (رسائل، قصائد، صور) لأغراض إعلانية أو لمحتوى مُولَّد بالذكاء الاصطناعي.',
    'privacy_s4_title': '4. المشاركة مع أطراف ثالثة',
    'privacy_s4_intro': 'قد تُنقل بياناتك، في الحدود الضرورية فقط، إلى:',
    'privacy_s4_bullet1':
        '• Google (تسجيل الدخول عبر Google، الإشعارات الفورية عبر Firebase)',
    'privacy_s4_bullet2': '• مزوّد دفع خارجي، لمعالجة المشتريات بأمان',
    'privacy_s4_bullet3':
        '• مزوّد الاستضافة الخاص بنا، الموجود في الاتحاد الأوروبي',
    'privacy_s4_note':
        '\nلا نبيع أو نؤجّر بياناتك أبداً لأطراف ثالثة لأغراض إعلانية.',
    'privacy_s5_title': '5. الأمان والاحتفاظ بالبيانات',
    'privacy_s5_body':
        'تُخزَّن بياناتك على خوادم موجودة في الاتحاد الأوروبي، مع تشفير كلمات المرور ورموز المصادقة. تُحفظ طالما حسابك نشط، وتُحذف نهائياً (مع بيانات Box الخاصة بكما، بشكل متسلسل) عند حذف الحساب.',
    'privacy_s6_title': '6. حقوقك',
    'privacy_s6_intro': 'يمكنك في أي وقت:',
    'privacy_s6_bullet1': '• الاطلاع على معلومات ملفك الشخصي وتعديلها',
    'privacy_s6_bullet2': '• حذف حسابك نهائياً من الإعدادات ← المنطقة الخطرة',
    'privacy_s6_bullet3': '• التواصل معنا لأي سؤال يتعلق ببياناتك',
    'privacy_s7_title': '7. الحد الأدنى للسن',
    'privacy_s7_body': 'Binome مخصّص للأشخاص البالغين 16 عاماً فأكثر.',
