    'terms_title': 'Ketentuan Layanan',
    'terms_last_update': 'Terakhir diperbarui: {year}',
    'terms_s1_title': '1. Penerimaan ketentuan',
    'terms_s1_body':
        'Dengan membuat akun atau menggunakan Binome, kamu menyetujui Ketentuan Layanan ini. Jika kamu tidak setuju, mohon untuk tidak menggunakan aplikasi ini.',
    'terms_s2_title': '2. Siapa yang dapat menggunakan Binome',
    'terms_s2_body':
        'Binome ditujukan untuk orang berusia 16 tahun ke atas, dalam konteks hubungan pasangan yang disetujui secara bebas. Setiap akun bersifat pribadi; berbagi kredensial dilarang.',
    'terms_s3_title': '3. Akunmu',
    'terms_s3_body':
        'Kamu bertanggung jawab menjaga kerahasiaan kredensialmu dan atas segala aktivitas yang dilakukan dari akunmu. Beri tahu kami segera jika ada akses tidak sah.',
    'terms_s4_title': '4. Hubungan pasangan ("Box")',
    'terms_s4_body':
        'Bergabung atau membuat Box menciptakan hubungan eksklusif antara dua orang. Kalian dapat mengakhiri hubungan ini kapan saja melalui Pengaturan → Zona bahaya; konten yang dibagikan (puisi, foto, jawaban permainan...) kemudian akan dihapus secara permanen.',
    'terms_s5_title': '5. Konten yang kamu bagikan',
    'terms_s5_body1':
        'Kamu tetap menjadi pemilik konten yang kamu kirim ke binômemu (pesan, foto, puisi, jawaban permainan). Kamu hanya memberi kami hak teknis untuk menyimpannya dan menyampaikannya ke binômemu, tidak pernah untuk digunakan demi tujuan lain.',
    'terms_s5_body2':
        'Kamu setuju untuk tidak mengirim konten ilegal, melecehkan, atau yang melanggar hak pihak ketiga.',
    'terms_s6_title': '6. Token virtual dan pembelian',
    'terms_s6_body':
        'Binome menawarkan Token virtual yang dapat dibeli, digunakan untuk fitur Toko tertentu. Pembelian diproses oleh penyedia pembayaran pihak ketiga kami. Token tidak memiliki nilai moneter nyata dan tidak dapat dikembalikan atau ditransfer, kecuali diwajibkan oleh hukum.',
    'terms_s7_title': '7. Penangguhan dan pengakhiran',
    'terms_s7_body':
        'Kami dapat menangguhkan atau menghapus akun jika terjadi pelanggaran nyata terhadap ketentuan ini (konten ilegal, pelecehan, penipuan). Kamu dapat menghapus akunmu kapan saja melalui Pengaturan → Zona bahaya.',
    'terms_s8_title': '8. Ketersediaan layanan',
    'terms_s8_body':
        'Kami berusaha sebaik mungkin menjaga ketersediaan Binome, tanpa menjamin ketersediaan tanpa gangguan. Layanan dapat berkembang, dihentikan sementara untuk pemeliharaan, atau diubah.',
    'terms_s9_title': '9. Batasan tanggung jawab',
    'terms_s9_body':
        'Binome disediakan "apa adanya". Sejauh diizinkan oleh hukum, kami tidak bertanggung jawab atas kerugian tidak langsung akibat penggunaan aplikasi.',
    'terms_s10_title': '10. Perubahan',
    'terms_s10_body':
        'Ketentuan ini dapat berubah; setiap perubahan substansial akan diberitahukan kepadamu di dalam aplikasi.',
    'terms_s11_title': '11. Kontak',
    'terms_s11_body':
        'Untuk pertanyaan apa pun tentang ketentuan ini: contact@binome-app.com.',
    'common_enable': 'Aktifkan',
    'notif_card_title': 'Notifikasi dinonaktifkan',
