    'contact_title': 'Hubungi kami',
    'contact_subtitle':
        'Ada pertanyaan, masalah, atau saran? Tulis kepada kami, kami akan membalas lewat email.',
    'contact_subject_label': 'Subjek',
    'contact_message_label': 'Pesan',
