    'privacy_title': 'Kebijakan Privasi',
    'privacy_last_update': 'Terakhir diperbarui: {year}',
    'privacy_s1_title': '1. Siapa kami',
    'privacy_s1_body1':
        'Binome adalah aplikasi seluler yang dirancang untuk pasangan, dibuat agar tetap menjadi ruang privat yang eksklusif untuk dua orang. Kebijakan ini menjelaskan data apa yang kami kumpulkan, mengapa, dan bagaimana kamu dapat mengontrolnya.',
    'privacy_s1_body2':
        'Untuk pertanyaan apa pun tentang datamu: contact@binome-app.com.',
    'privacy_s2_title': '2. Data yang kami kumpulkan',
    'privacy_s2_sub1_title': 'Informasi akun',
    'privacy_s2_sub1_body':
        'Email, nama depan, nama belakang, jenis kelamin, negara domisili, foto profil, bahasa dan tema pilihan. Jika kamu masuk melalui Google, sebagian informasi ini berasal langsung dari akun Google-mu.',
    'privacy_s2_sub2_title': 'Informasi terkait pasanganmu ("Box")',
    'privacy_s2_sub2_body':
        'Kode pasangan, tanggal "bersama sejak", foto pasangan, moto/kutipan bersama, dan preferensi pengingatmu (ritual malam/pagi).',
    'privacy_s2_sub3_title': 'Konten yang kalian pertukarkan',
    'privacy_s2_sub3_body':
        'Puisi, hadiah, pesan, foto, jawaban permainan, reaksi — semua yang kamu kirim ke binômemu di dalam aplikasi.',
    'privacy_s2_sub4_title': 'Data pembayaran',
    'privacy_s2_sub4_body':
        'Jika kamu membeli Token virtual, informasi pembayaran diproses langsung oleh penyedia pembayaran pihak ketiga kami; kami tidak pernah menyimpan detail bank lengkapmu, hanya riwayat transaksimu (jumlah, mata uang, tanggal).',
    'privacy_s2_sub5_title': 'Data teknis',
    'privacy_s2_sub5_body':
        'Token notifikasi push (untuk mengirimkan pengingat), stempel waktu aktivitas terakhir, dan informasi perangkat yang diperlukan agar layanan berjalan dengan baik.',
    'privacy_s3_title': '3. Bagaimana kami menggunakan data ini',
    'privacy_s3_bullet1': '• Menjalankan akunmu dan ruang pasanganmu',
    'privacy_s3_bullet2':
        '• Mengirimkan notifikasi yang telah kamu aktifkan (pengingat, peringatan)',
    'privacy_s3_bullet3': '• Memproses pembelian Token virtualmu',
    'privacy_s3_bullet4': '• Menjaga keamanan dan mencegah penyalahgunaan',
    'privacy_s3_bullet5': '• Meningkatkan aplikasi',
    'privacy_s3_note':
        '\nKami tidak pernah menggunakan pertukaran pasanganmu (pesan, puisi, foto) untuk iklan atau konten yang dihasilkan AI.',
    'privacy_s4_title': '4. Berbagi dengan pihak ketiga',
    'privacy_s4_intro':
        'Datamu dapat dibagikan, sebatas yang benar-benar diperlukan, kepada:',
    'privacy_s4_bullet1':
        '• Google (Masuk dengan Google, notifikasi push melalui Firebase)',
    'privacy_s4_bullet2':
        '• Penyedia pembayaran pihak ketiga, untuk pemrosesan pembelian yang aman',
    'privacy_s4_bullet3':
        '• Penyedia hosting kami, yang berlokasi di Uni Eropa',
    'privacy_s4_note':
        '\nKami tidak pernah menjual atau menyewakan datamu ke pihak ketiga untuk tujuan iklan.',
    'privacy_s5_title': '5. Keamanan dan penyimpanan',
    'privacy_s5_body':
        'Datamu disimpan di server yang berlokasi di Uni Eropa, dengan kata sandi dan token autentikasi terenkripsi. Data disimpan selama akunmu aktif, dan dihapus secara permanen (bersama data Box-mu, secara berjenjang) jika kamu menghapus akun.',
    'privacy_s6_title': '6. Hakmu',
    'privacy_s6_intro': 'Kapan saja kamu dapat:',
    'privacy_s6_bullet1': '• Melihat dan mengedit informasi profilmu',
    'privacy_s6_bullet2':
        '• Menghapus akunmu secara permanen dari Pengaturan → Zona bahaya',
    'privacy_s6_bullet3':
        '• Menghubungi kami untuk pertanyaan apa pun tentang datamu',
    'privacy_s7_title': '7. Usia minimum',
    'privacy_s7_body': 'Binome ditujukan untuk orang berusia 16 tahun ke atas.',
    'privacy_s8_title': '8. Perubahan',
    'privacy_s8_body':
        'Kebijakan ini dapat berubah; setiap perubahan substansial akan diberitahukan kepadamu di dalam aplikasi.',
