    'common_cancel': 'Отмена',
    'contact_title': 'Связаться с нами',
    'contact_subtitle':
        'Есть вопрос, проблема или предложение? Напишите нам, мы ответим по email.',
    'contact_subject_label': 'Тема',
    'contact_message_label': 'Сообщение',
    'contact_send': 'Отправить',
    'contact_sent_snackbar':
        'Сообщение отправлено — мы ответим вам по email. 💕',
    'contact_generic_error': 'Не удалось отправить сообщение сейчас.',
    'privacy_title': 'Политика конфиденциальности',
    'privacy_last_update': 'Последнее обновление: {year}',
    'privacy_s1_title': '1. Кто мы',
    'privacy_s1_body1':
        'Binome — это мобильное приложение для пар, созданное как приватное пространство исключительно для двоих. Эта политика объясняет, какие данные мы собираем, зачем и как вы можете их контролировать.',
    'privacy_s1_body2':
        'По любым вопросам о ваших данных: contact@binome-app.com.',
    'privacy_s2_title': '2. Какие данные мы собираем',
    'privacy_s2_sub1_title': 'Информация об аккаунте',
    'privacy_s2_sub1_body':
        'Email, имя, фамилия, пол, страна проживания, фото профиля, предпочитаемые язык и тема. Если вы входите через Google, часть этой информации поступает напрямую из вашего аккаунта Google.',
    'privacy_s2_sub2_title': 'Информация, связанная с вашей парой («Box»)',
    'privacy_s2_sub2_body':
        'Код сопряжения, дата «вместе с», совместное фото, общий девиз/цитата и ваши настройки напоминаний (вечерние/утренние ритуалы).',
    'privacy_s2_sub3_title': 'Контент, которым вы обмениваетесь',
    'privacy_s2_sub3_body':
        'Стихи, подарки, сообщения, фото, ответы в играх, реакции — всё, что вы отправляете своему бином внутри приложения.',
    'privacy_s2_sub4_title': 'Платёжные данные',
    'privacy_s2_sub4_body':
        'При покупке виртуальных Token платёжная информация обрабатывается напрямую нашим сторонним платёжным провайдером; мы никогда не храним полные банковские данные, только историю ваших транзакций (сумма, валюта, дата).',
    'privacy_s2_sub5_title': 'Технические данные',
    'privacy_s2_sub5_body':
        'Токен push-уведомлений (для отправки напоминаний), отметка времени последней активности и информация об устройстве, необходимая для корректной работы сервиса.',
    'privacy_s3_title': '3. Как мы используем эти данные',
    'privacy_s3_bullet1': '• Для работы вашего аккаунта и пространства пары',
    'privacy_s3_bullet2':
        '• Для отправки включённых вами уведомлений (напоминания, оповещения)',
    'privacy_s3_bullet3': '• Для обработки покупок виртуальных Token',
    'privacy_s3_bullet4':
        '• Для обеспечения безопасности и предотвращения злоупотреблений',
    'privacy_s3_bullet5': '• Для улучшения приложения',
    'privacy_s3_note':
        '\nМы никогда не используем переписку вашей пары (сообщения, стихи, фото) для рекламы или контента, созданного ИИ.',
    'privacy_s4_title': '4. Передача третьим лицам',
    'privacy_s4_intro':
        'Ваши данные могут передаваться, строго в необходимых пределах:',
    'privacy_s4_bullet1':
        '• Google (вход через Google Sign-In, push-уведомления через Firebase)',
    'privacy_s4_bullet2':
        '• Сторонний платёжный провайдер — для безопасной обработки покупок',
    'privacy_s4_bullet3':
        '• Наш хостинг-провайдер, расположенный в Европейском союзе',
    'privacy_s4_note':
        '\nМы никогда не продаём и не сдаём в аренду ваши данные третьим лицам в рекламных целях.',
    'privacy_s5_title': '5. Безопасность и хранение',
    'privacy_s5_body':
        'Ваши данные хранятся на серверах, расположенных в Европейском союзе, с шифрованием паролей и токенов аутентификации. Они хранятся, пока ваш аккаунт активен, и удаляются безвозвратно (вместе с данными вашего Box, каскадно) при удалении аккаунта.',
    'privacy_s6_title': '6. Ваши права',
    'privacy_s6_intro': 'В любой момент вы можете:',
    'privacy_s6_bullet1':
        '• Просматривать и изменять информацию своего профиля',
    'privacy_s6_bullet2':
        '• Безвозвратно удалить аккаунт в Настройках → Опасная зона',
    'privacy_s6_bullet3': '• Связаться с нами по любому вопросу о ваших данных',
