    'terms_title': 'Termos de Serviço',
    'terms_last_update': 'Última atualização: {year}',
    'terms_s1_title': '1. Aceitação dos termos',
    'terms_s1_body':
        'Ao criar uma conta ou usar o Binome, aceitas estes Termos de Serviço. Se não concordares, por favor não utilizes a aplicação.',
    'terms_s2_title': '2. Quem pode usar o Binome',
    'terms_s2_body':
        'O Binome destina-se a pessoas com 16 anos ou mais, no contexto de uma relação de casal livremente consentida. Cada conta é pessoal; é proibido partilhar credenciais.',
    'terms_s3_title': '3. A tua conta',
    'terms_s3_body':
        'És responsável por manter a confidencialidade das tuas credenciais e por qualquer atividade realizada a partir da tua conta. Avisa-nos imediatamente em caso de acesso não autorizado.',
    'terms_s4_title': '4. O vínculo de casal («Box»)',
    'terms_s4_body':
        'Juntar-se a uma Box ou criá-la estabelece um vínculo exclusivo entre duas pessoas. Podem terminar este vínculo a qualquer momento em Definições → Zona de perigo; o conteúdo partilhado (poemas, fotos, respostas a jogos...) é então eliminado definitivamente.',
    'terms_s5_title': '5. Conteúdo que partilhas',
    'terms_s5_body1':
        'Manténs a propriedade do conteúdo que envias ao teu binômio (mensagens, fotos, poemas, respostas a jogos). Concedes-nos apenas o direito técnico de o alojar e entregá-lo ao teu binômio, nunca de o usar para outros fins.',
    'terms_s5_body2':
        'Comprometes-te a não enviar conteúdo ilegal, assediador ou que viole os direitos de terceiros.',
    'terms_s6_title': '6. Tokens virtuais e compras',
    'terms_s6_body':
        'O Binome oferece Tokens virtuais compráveis, utilizáveis em certas funcionalidades da Loja. As compras são processadas pelo nosso prestador de pagamento terceiro. Os Tokens não têm valor monetário real e não são reembolsáveis nem transferíveis, salvo obrigação legal em contrário.',
    'terms_s7_title': '7. Suspensão e rescisão',
    'terms_s7_body':
        'Podemos suspender ou eliminar uma conta em caso de violação manifesta destes termos (conteúdo ilegal, assédio, fraude). Podes eliminar a tua conta a qualquer momento em Definições → Zona de perigo.',
    'terms_s8_title': '8. Disponibilidade do serviço',
    'terms_s8_body':
        'Fazemos o possível para manter o Binome disponível, sem garantir disponibilidade ininterrupta. O serviço pode evoluir, ser temporariamente interrompido para manutenção ou modificado.',
    'terms_s9_title': '9. Limitação de responsabilidade',
    'terms_s9_body':
        'O Binome é fornecido "tal como está". Na medida permitida por lei, não somos responsáveis por danos indiretos resultantes do uso da aplicação.',
    'terms_s10_title': '10. Modificações',
    'terms_s10_body':
        'Estes termos podem evoluir; qualquer modificação substancial ser-te-á comunicada dentro da aplicação.',
    'terms_s11_title': '11. Contacto',
    'terms_s11_body':
        'Para qualquer questão relativa a estes termos: contact@binome-app.com.',
