    'privacy_title': 'Política de Privacidade',
    'privacy_last_update': 'Última atualização: {year}',
    'privacy_s1_title': '1. Quem somos',
    'privacy_s1_body1':
        'Binome é uma aplicação móvel dedicada a casais, pensada para continuar sendo um espaço privado e exclusivo para duas pessoas. Esta política explica quais dados recolhemos, porquê, e como podes controlá-los.',
    'privacy_s1_body2':
        'Para qualquer questão relativa aos teus dados: contact@binome-app.com.',
    'privacy_s2_title': '2. Os dados que recolhemos',
    'privacy_s2_sub1_title': 'Informações da conta',
    'privacy_s2_sub1_body':
        'Email, primeiro nome, apelido, género, país de residência, foto de perfil, idioma e tema preferidos. Se te ligares através do Google, algumas destas informações vêm diretamente da tua conta Google.',
    'privacy_s2_sub2_title': 'Informações ligadas ao vosso casal («Box»)',
    'privacy_s2_sub2_body':
        'O código de emparelhamento, a data "juntos desde", uma foto de casal, uma divisa/citação partilhada, e as vossas preferências de lembretes (rituais da noite/manhã).',
    'privacy_s2_sub3_title': 'Conteúdos que trocam',
    'privacy_s2_sub3_body':
        'Poemas, presentes, mensagens, fotos, respostas a jogos, reações — tudo o que enviam ao vosso binômio dentro da aplicação.',
    'privacy_s2_sub4_title': 'Dados de pagamento',
    'privacy_s2_sub4_body':
        'Se comprares Tokens virtuais, as informações de pagamento são processadas diretamente pelo nosso prestador de pagamento terceiro; nunca armazenamos os teus dados bancários completos, apenas o histórico das tuas transações (valor, moeda, data).',
    'privacy_s2_sub5_title': 'Dados técnicos',
    'privacy_s2_sub5_body':
        'Token de notificação push (para te enviar lembretes), registo temporal da última atividade, e informações do dispositivo necessárias ao bom funcionamento do serviço.',
    'privacy_s3_title': '3. Como usamos estes dados',
    'privacy_s3_bullet1':
        '• Fazer funcionar a tua conta e o vosso espaço de casal',
    'privacy_s3_bullet2':
        '• Enviar-te as notificações que ativaste (lembretes, alertas)',
    'privacy_s3_bullet3': '• Processar as tuas compras de Tokens virtuais',
    'privacy_s3_bullet4': '• Garantir a segurança e prevenir abusos',
    'privacy_s3_bullet5': '• Melhorar a aplicação',
    'privacy_s3_note':
        '\nNunca usamos as vossas trocas de casal (mensagens, poemas, fotos) para fins publicitários ou para conteúdo gerado por IA.',
    'privacy_s4_title': '4. Partilha com terceiros',
    'privacy_s4_intro':
        'Os teus dados podem ser transmitidos, na estrita medida necessária, a:',
    'privacy_s4_bullet1':
        '• Google (início de sessão via Google Sign-In, notificações push via Firebase)',
    'privacy_s4_bullet2':
        '• Um prestador de pagamento terceiro, para o processamento seguro de compras',
    'privacy_s4_bullet3':
        '• O nosso fornecedor de alojamento, situado na União Europeia',
    'privacy_s4_note':
        '\nNunca vendemos nem alugamos os teus dados a terceiros para fins publicitários.',
    'privacy_s5_title': '5. Segurança e conservação',
    'privacy_s5_body':
        'Os teus dados são armazenados em servidores situados na União Europeia, com cifragem das palavras-passe e tokens de autenticação. São conservados enquanto a tua conta estiver ativa, e eliminados definitivamente (juntamente com os da vossa Box, em cascata) em caso de eliminação da conta.',
    'privacy_s6_title': '6. Os teus direitos',
    'privacy_s6_intro': 'Podes, a qualquer momento:',
    'privacy_s6_bullet1':
        '• Consultar e modificar as informações do teu perfil',
    'privacy_s6_bullet2':
        '• Eliminar a tua conta definitivamente em Definições → Zona de perigo',
    'privacy_s6_bullet3':
        '• Contactar-nos para qualquer questão sobre os teus dados',
    'privacy_s7_title': '7. Idade mínima',
    'privacy_s7_body': 'Binome destina-se a pessoas com 16 anos ou mais.',
    'privacy_s8_title': '8. Modificações',
    'privacy_s8_body':
        'Esta política pode evoluir; qualquer modificação substancial ser-te-á comunicada dentro da aplicação.',
