    'privacy_title': 'Gizlilik Politikası',
    'privacy_last_update': 'Son güncelleme: {year}',
    'privacy_s1_title': '1. Biz kimiz',
    'privacy_s1_body1':
        'Binome, çiftler için tasarlanmış, iki kişiye özel kalması amaçlanan mobil bir uygulamadır. Bu politika, hangi verileri, neden topladığımızı ve bunları nasıl kontrol edebileceğini açıklar.',
    'privacy_s1_body2':
        'Verilerinle ilgili herhangi bir soru için: contact@binome-app.com.',
    'privacy_s2_title': '2. Topladığımız veriler',
    'privacy_s2_sub1_title': 'Hesap bilgileri',
    'privacy_s2_sub1_body':
        'E-posta, ad, soyad, cinsiyet, ikamet ülkesi, profil fotoğrafı, tercih edilen dil ve tema. Google ile giriş yaparsan, bu bilgilerin bir kısmı doğrudan Google hesabından gelir.',
    'privacy_s2_sub2_title': 'Çiftinle ilgili bilgiler ("Box")',
    'privacy_s2_sub2_body':
        'Eşleştirme kodun, "beraber olduğunuz tarih" bilgisi, bir çift fotoğrafı, ortak bir slogan/söz ve hatırlatma tercihlerin (akşam/sabah ritüelleri).',
    'privacy_s2_sub3_title': 'Paylaştığınız içerikler',
    'privacy_s2_sub3_body':
        'Şiirler, hediyeler, mesajlar, fotoğraflar, oyun cevapları, tepkiler — uygulama içinde binômene gönderdiğin her şey.',
    'privacy_s2_sub4_title': 'Ödeme verileri',
    'privacy_s2_sub4_body':
        'Sanal Token satın alırsan, ödeme bilgileri doğrudan üçüncü taraf ödeme sağlayıcımız tarafından işlenir; tam banka bilgilerini asla saklamayız, yalnızca işlem geçmişini (tutar, para birimi, tarih) tutarız.',
    'privacy_s2_sub5_title': 'Teknik veriler',
    'privacy_s2_sub5_body':
        'Anlık bildirim token\'ı (sana hatırlatma göndermek için), son etkinlik zaman damgası ve hizmetin düzgün çalışması için gerekli cihaz bilgileri.',
    'privacy_s3_title': '3. Bu verileri nasıl kullanıyoruz',
    'privacy_s3_bullet1': '• Hesabını ve çift alanını çalıştırmak için',
    'privacy_s3_bullet2':
        '• Etkinleştirdiğin bildirimleri göndermek için (hatırlatmalar, uyarılar)',
    'privacy_s3_bullet3': '• Sanal Token satın alımlarını işlemek için',
    'privacy_s3_bullet4':
        '• Güvenliği sağlamak ve kötüye kullanımı önlemek için',
    'privacy_s3_bullet5': '• Uygulamayı geliştirmek için',
