    'terms_title': '利用規約',
    'terms_last_update': '最終更新日：{year}',
    'terms_s1_title': '1. 規約への同意',
    'terms_s1_body':
        'アカウントを作成する、またはBinomeを利用することで、本利用規約に同意したものとみなされます。同意いただけない場合は、アプリのご利用をお控えください。',
    'terms_s2_title': '2. 利用対象者',
    'terms_s2_body':
        'Binomeは、双方合意のカップル関係にある16歳以上の方を対象としています。アカウントは個人専用であり、認証情報の共有は禁止されています。',
    'terms_s3_title': '3. アカウントについて',
    'terms_s3_body':
        '認証情報の機密保持およびアカウントから行われるすべての操作について、ご自身に責任があります。不正アクセスがあった場合は直ちにご連絡ください。',
    'terms_s4_title': '4. カップルのつながり（「Box」）',
    'terms_s4_body':
        'Boxへの参加または作成により、二人だけの専用のつながりが生まれます。設定→危険ゾーンからいつでもこのつながりを解消できます。その際、共有されたコンテンツ（詩、写真、ゲームの回答など）は完全に削除されます。',
    'terms_s5_title': '5. あなたが共有するコンテンツ',
    'terms_s5_body1':
        'バイノームに送信するコンテンツ（メッセージ、写真、詩、ゲームの回答）の所有権はあなたに帰属します。あなたは当社に対し、これをホスティングしバイノームに配信するための技術的権利のみを許諾するものとし、それ以外の目的での利用を許諾するものではありません。',
    'terms_s5_body2': '違法な、嫌がらせに当たる、または第三者の権利を侵害するコンテンツを送信しないことに同意するものとします。',
    'terms_s6_title': '6. 仮想Tokenと購入',
    'terms_s6_body':
        'Binomeは購入可能な仮想Tokenを提供しており、ショップの一部機能に利用できます。購入は第三者の決済プロバイダーによって処理されます。Tokenには実際の金銭的価値はなく、法律で義務付けられる場合を除き、返金や譲渡はできません。',
    'terms_s7_title': '7. 停止と解約',
    'terms_s7_body':
        '本規約への明らかな違反（違法コンテンツ、嫌がらせ、詐欺など）があった場合、アカウントを停止または削除することがあります。設定→危険ゾーンからいつでもアカウントを削除できます。',
    'terms_s8_title': '8. サービスの提供状況',
    'terms_s8_body':
        '当社はBinomeを継続的にご利用いただけるよう努めますが、中断のない提供を保証するものではありません。サービスは変更されたり、メンテナンスのため一時的に中断されたりする場合があります。',
    'terms_s9_title': '9. 責任の制限',
    'terms_s9_body':
        'Binomeは「現状有姿」で提供されます。法律で許容される範囲において、アプリの利用に起因する間接的損害について当社は責任を負いません。',
    'terms_s10_title': '10. 変更',
    'terms_s10_body': '本規約は変更されることがあります。重要な変更があった場合はアプリ内でお知らせします。',
    'terms_s11_title': '11. お問い合わせ',
    'terms_s11_body': '本規約に関するご質問は、contact@binome-app.com までご連絡ください。',
